const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={token:'',course:null,software:[],progress:{lessons:[],preferences:{}},health:null,lesson:'w1-1',hints:{},view:'learn',result:null,previous:null,run:null,activeRun:null,motorPending:false,terminal:null,socket:null,resize:null,motorConfig:{mode:'closed',voltage:12,target_rpm:900,kp:.08,ki:.6,duration:5,load_time:2.5,load_Nm:.03,fault:'none',anti_windup:true}};
const root=$('#view-root'); let toastTimer,renderVersion=0;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
async function api(path,method='GET',body){const options={method,headers:{'X-Course-Token':state.token}};if(body!==undefined){options.body=JSON.stringify(body);options.headers['Content-Type']='application/json'}const response=await fetch('/api'+path,options);if(!response.ok){let data;try{data=await response.json()}catch{data={error:'本地服务没有正常响应。'}}throw Error(data.error||'请求未完成')}return response.json()}
async function download(path,name){try{const r=await fetch('/api'+path,{headers:{'X-Course-Token':state.token}});if(!r.ok){const data=await r.json();throw Error(data.error)}const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}catch(e){toast(e.message)}}
function safeLink(url){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}}
function currentLesson(){return state.course.lessons.find(l=>l.id===state.lesson)||state.course.lessons[0]}
function progressOf(id){return state.progress.lessons.find(l=>l.lesson===id)||{score:0,checked:0}}
function completed(id){const p=progressOf(id);return p.checked&&p.score>=80&&p.read_at}
function navigate(view,detail){location.hash=detail?`${view}/${detail}`:view}
function closeTerminal(){state.resize?.disconnect();state.resize=null;state.socket?.close();state.socket=null;state.terminal?.dispose();state.terminal=null}
function updateNav(){const count=state.course.lessons.filter(l=>completed(l.id)).length;$('#progress-label').textContent=`${count} / 24`;$('#overall-progress').value=count;$$('.main-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#course-nav').innerHTML=state.course.weeks.map(w=>{const active=currentLesson().week===w.id;return `<button class="week-link ${active&&state.view==='learn'?'active':''}" data-lesson="w${w.id}-1">${String(w.id).padStart(2,'0')}<span>${esc(w.title)}</span></button>${active&&state.view==='learn'?`<div class="lesson-subnav">${state.course.lessons.filter(l=>l.week===w.id).map(l=>`<button class="${state.lesson===l.id?'active':''}" data-lesson="${l.id}">${completed(l.id)?'✓ ':''}${esc(l.title)}</button>`).join('')}</div>`:''}`}).join('')}
function heading(eyebrow,title,description,meta=''){return `<section class="lesson-heading"><div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1><p>${esc(description)}</p>${meta}</section>`}
function render(){if(!state.course)return;renderVersion++;closeTerminal();const parts=location.hash.slice(1).split('/');state.view=['learn','motor','software','tracks','portfolio'].includes(parts[0])?parts[0]:'learn';if(state.view==='learn'&&parts[1]&&state.course.lessons.some(l=>l.id===parts[1]))state.lesson=parts[1];const labels={learn:'项目课程',motor:'虚拟电机实验台',software:'软件与环境',tracks:'专业进阶路线',portfolio:'学习与作品'};$('#breadcrumb').innerHTML=`${labels[state.view]} <span>/</span> ${state.view==='learn'?`第 ${currentLesson().week} 周`:'机械工程实践'}`;updateNav();({learn:renderLesson,motor:renderMotor,software:()=>renderSoftware(parts[1]),tracks:renderTracks,portfolio:renderPortfolio})[state.view]();$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'instant'})}
function renderLesson(){const l=currentLesson(),p=progressOf(l.id),week=state.course.weeks.find(w=>w.id===l.week);const objectives=l.objectives.map(x=>`<li>${esc(x)}</li>`).join('');root.innerHTML=heading(`PROJECT ${String(l.week).padStart(2,'0')} <span>共同基础 · ${esc(week.project)}</span>`,l.title,l.summary,`<div class="lesson-meta"><span>${l.order} / 04 单元</span><span>${esc(l.duration)}${typeof l.duration==='number'?' 分钟':''}</span><span>${p.checked?'实验检查已通过':'实践后点击检查'}</span></div>`)+`<div class="learning-grid"><article class="lesson-body"><div class="section-index">本课目标 <span>理解 → 操作 → 验证</span></div><ul class="objectives">${objectives}</ul>${l.sections.map((s,i)=>`<section class="teaching-section"><h2><span class="section-number">${String(i+1).padStart(2,'0')}</span>${esc(s.title)}</h2>${String(s.body).split(/\n\s*\n/).map(t=>`<p>${esc(t)}</p>`).join('')}</section>`).join('')}<h2>在终端试一试</h2>${l.commands.map((c,i)=>`<div class="command-card"><div class="command-top"><span>步骤 ${i+1}</span><button class="copy-button" data-copy="${esc(c.command)}">复制命令</button></div><pre><code>${esc(c.command)}</code></pre><p>${esc(c.explanation)}</p><div class="expected"><b>检查结果</b> ${esc(c.expected)}</div></div>`).join('')}<div class="learning-note"><b>本课交付</b><p>${esc(l.deliverable)}</p></div>${l.softwareIds?.length?`<div class="software-links">本课软件 ${l.softwareIds.map(id=>`<button class="text-link" data-software="${esc(id)}">${esc(state.software.find(s=>s.id===id)?.name||id)}</button>`).join('')}</div>`:''}<details class="glossary"><summary>中英术语速查</summary><dl>${l.glossary.map(g=>`<dt>${esc(g.en)}</dt><dd>${esc(g.zh)}</dd>`).join('')}</dl></details><section class="quiz-section"><h2>检查你的理解</h2><p class="muted">可以重试。理解题与真实实验分别记录。</p><form id="quiz-form">${l.quiz.map((q,i)=>`<fieldset><legend>${i+1}. ${esc(q.question)}</legend>${q.options.map((o,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}" ${p.quiz?.[i]===j?'checked':''} required><span>${esc(o)}</span></label>`).join('')}</fieldset>`).join('')}<button class="primary" type="submit">提交理解题</button><div id="quiz-feedback" aria-live="polite"></div></form></section><div class="lesson-bottom"><button class="secondary" id="mark-read">${p.read_at?'✓ 已记录阅读':'标记已读'}</button><button class="primary" id="next-lesson">${l.id==='w6-4'?'查看作品记录':'下一单元 →'}</button></div></article><aside class="lab-panel"><div class="panel-title"><span>实践工作区</span><span class="tag">真实 Linux</span></div><div class="terminal-toolbar"><span>student · /workspace</span><span id="terminal-state">未连接</span></div><div id="terminal-area" class="terminal-empty"><span class="terminal-symbol">&gt;_</span><h3>${state.health?.ready?'开始本周实验':'准备你的实验环境'}</h3><p>${state.health?.ready?'实验文件保存在当前项目中。切换项目会停止上一项目的程序。':'需要 rootless Docker 与课程镜像。环境未就绪时，课程和网页电机实验仍可使用。'}</p><button class="primary" id="start-lab">启动第 ${l.week} 周实验</button><button class="terminal-link" data-view="software">查看环境准备</button></div><div id="lab-status" aria-live="polite"></div><div class="lab-controls"><button class="secondary" id="connect-lab">连接终端</button><button class="secondary" id="export-lab">导出文件</button><button class="text-link" id="reset-lab">重置</button><button class="text-link" id="stop-lab">停止</button></div><div class="task-card"><div class="eyebrow">当前任务</div><h3>${esc(l.tasks[0].title)}</h3><p>${esc(l.tasks[0].description)}</p><button class="primary full-width" id="check-task">检查任务结果</button><div id="check-result" aria-live="polite">${p.checked?'<p class="success-text">✓ 上次检查通过；修改后可再次检查。</p>':''}</div><button class="text-link" id="show-hint">需要一点提示？</button><div id="hint-content"></div><details class="solution"><summary>查看参考解</summary><p>先尝试完成，再比较不同方法。执行前确认当前目录。</p><pre>${esc(l.tasks[0].solution)}</pre></details></div><div class="lab-help">本地实验不需要真实电机。完成命令后，以输出与文件状态确认结果。</div></aside></div>`;
$('#quiz-form').onsubmit=async e=>{e.preventDefault();try{const answers=l.quiz.map((_,i)=>Number(new FormData(e.target).get('q'+i)));state.progress=await api('/progress','POST',{lesson:l.id,answers});$('#quiz-feedback').innerHTML=l.quiz.map((q,i)=>`<div class="quiz-feedback ${answers[i]===q.answer?'correct':'incorrect'}"><b>${answers[i]===q.answer?'✓ 正确':'再想一想'}</b><p>${esc(q.explanation)}</p></div>`).join('');updateNav()}catch(e){toast(e.message)}};
$('#mark-read').onclick=async()=>{state.progress=await api('/progress','POST',{lesson:l.id,read:true});$('#mark-read').textContent='✓ 已记录阅读';updateNav()};
$('#next-lesson').onclick=()=>{const index=state.course.lessons.findIndex(x=>x.id===l.id);const next=state.course.lessons[index+1];navigate(next?'learn':'portfolio',next?.id)};
$('#show-hint').onclick=()=>{state.hints[l.id]=Math.min((state.hints[l.id]||0)+1,3);$('#hint-content').innerHTML=l.tasks[0].hints.slice(0,state.hints[l.id]).map((h,i)=>`<p class="hint"><b>提示 ${i+1}</b> ${esc(h)}</p>`).join('');$('#show-hint').textContent=state.hints[l.id]===3?'已显示全部提示':'再给我一点提示'};
$('#start-lab').onclick=()=>startLab(l.week);$('#connect-lab').onclick=()=>connectTerminal(l.week);$('#export-lab').onclick=()=>download(`/labs/${l.week}/export`,`week-${l.week}-project.tar.gz`);
$('#stop-lab').onclick=async()=>{try{closeTerminal();await api(`/labs/${l.week}/stop`,'POST');toast('文件已保留，运行中的程序已停止。');render()}catch(e){toast(e.message)}};
$('#reset-lab').onclick=async()=>{if(!await confirmAction('重置本周实验？','本周的实验文件、安装状态和密钥将被清除。学习尝试记录保留，本轮任务需重新验证。建议先导出文件。'))return;try{closeTerminal();await api(`/labs/${l.week}/reset`,'POST');state.progress=await api('/progress');toast('本周实验已重置。');render()}catch(e){toast(e.message)}};
$('#check-task').onclick=async()=>{const btn=$('#check-task');btn.disabled=true;btn.textContent='正在检查实际结果…';try{const r=await api('/check','POST',{lesson:l.id});$('#check-result').innerHTML=`<div class="check-feedback ${r.status==='passed'?'correct':'incorrect'}"><b>${r.status==='passed'?'✓ 检查通过':r.status==='environment_error'?'环境需要准备':'任务尚未完成'}</b>${(r.items||[{message:r.message}]).map(x=>`<p>${esc(x.message||x.title)}</p>`).join('')}</div>`;state.progress=await api('/progress');updateNav()}catch(e){$('#check-result').innerHTML=`<p class="error-box">${esc(e.message)}</p>`}finally{btn.disabled=false;btn.textContent='检查任务结果'}};
}
async function startLab(week){const btn=$('#start-lab');if(btn){btn.disabled=true;btn.textContent='正在准备实验…'}try{const r=await api(`/labs/${week}/start`,'POST');if($('#lab-status'))$('#lab-status').innerHTML=r.fingerprint?`<div class="fingerprint"><b>远程主机指纹</b><code>${esc(r.fingerprint)}</code>首次 SSH 连接前，请核对这个指纹。</div>`:'';await connectTerminal(week);refreshHealth()}catch(e){if($('#lab-status'))$('#lab-status').innerHTML=`<div class="error-box">${esc(e.message)}</div>`}finally{if(btn?.isConnected){btn.disabled=false;btn.textContent=`启动第 ${week} 周实验`}}}
async function connectTerminal(week){if(!window.Terminal||!window.FitAddon){toast('终端组件未加载，请检查本地资源。');return}closeTerminal();const area=$('#terminal-area');area.className='terminal-live';area.innerHTML='';const term=new window.Terminal({fontFamily:'"DejaVu Sans Mono",Consolas,monospace',fontSize:13,cursorBlink:true,scrollback:1500,convertEol:false,allowProposedApi:false,theme:{background:'#111a2b',foreground:'#d9e3f7',cursor:'#91a6ff',selectionBackground:'#445b93'}});const fit=new window.FitAddon.FitAddon();term.loadAddon(fit);term.open(area);fit.fit();state.terminal=term;const ws=new WebSocket(`ws://${location.host}/api/labs/${week}/terminal`,['linuxlab',state.token]);state.socket=ws;ws.binaryType='arraybuffer';ws.onopen=()=>{if($('#terminal-state'))$('#terminal-state').textContent='已连接';ws.send(JSON.stringify({type:'resize',cols:term.cols,rows:term.rows}));term.focus()};ws.onmessage=e=>{if(e.data instanceof ArrayBuffer)term.write(new Uint8Array(e.data))};ws.onclose=()=>{if($('#terminal-state'))$('#terminal-state').textContent='连接已断开';if(state.terminal===term)term.writeln('\r\n\x1b[33m[连接已断开。文件保留；点击“连接终端”重连。]\x1b[0m')};ws.onerror=()=>toast('终端无法连接。请先启动本周实验；服务重启后需刷新页面。');term.onData(data=>{if(ws.readyState===WebSocket.OPEN)ws.send(JSON.stringify({type:'input',data}))});term.parser.registerOscHandler(52,()=>true);state.resize=new ResizeObserver(()=>{try{fit.fit();if(ws.readyState===WebSocket.OPEN)ws.send(JSON.stringify({type:'resize',cols:term.cols,rows:term.rows}))}catch{}});state.resize.observe(area)}
async function refreshHealth(){try{state.health=await api('/health');$('#environment-label').textContent=state.health.ready?'实验环境已就绪':'实验环境待准备';$('.status-dot').classList.toggle('ready',state.health.ready)}catch{$('#environment-label').textContent='本地服务未连接'}}
function renderSoftware(detail){const h=state.health;root.innerHTML=heading('ENGINEERING TOOLBOX <span>按项目准备</span>','软件与实验环境','先检查，再安装。每个工具都附用途、安装位置、验证方法和常见问题。')+`<section class="environment-card"><div><div class="eyebrow">本机环境</div><h2>${h?.ready?'基础实验环境已就绪':'先准备隔离的实验环境'}</h2><p>${h?.issues?.length?esc(h.issues.join('\n')):'课程使用本机服务，命令在课程容器中执行。'}</p><div class="environment-facts"><span>Python ${esc(h?.python||'检查中')}</span><span>磁盘可用 ${h?.disk_free_gb??'—'} GB</span><span>rootless Docker ${h?.rootless?'✓':'待准备'}</span></div></div><button class="secondary" id="refresh-health">重新检查</button></section><details class="setup-guide" ${!h?.ready?'open':''}><summary>首次使用：启动平台和实验镜像</summary><p>以下命令在本机终端、教程项目目录中运行。网页不会执行宿主机命令。先按 <a href="https://docs.docker.com/engine/security/rootless/" target="_blank" rel="noopener noreferrer">Docker 官方 rootless 安装说明</a>准备运行环境，确认用户服务和 cgroup v2 可用。</p>${commandBlock('./start.sh','启动本机课程。首次使用请先运行 python3 scripts/bootstrap.py 安装课程服务依赖。')}${commandBlock('./scripts/prepare-labs.sh','准备基础实验镜像；首次需要联网下载并核对磁盘空间。')}${commandBlock('./scripts/prepare-labs.sh --modelica','第 6 周再准备 OpenModelica 软件包缓存。体积较大，按需安装。')}<p class="muted">受限容器或没有 systemd 用户服务的环境可能不能运行 rootless Docker。课程阅读与网页电机计算可独立使用；真实终端需要在符合条件的 Ubuntu 主机上准备。</p></details><div class="software-filter"><button class="chip active" data-filter="all">全部工具</button><button class="chip" data-filter="基础必修">基础必修</button><button class="chip" data-filter="方向按需">方向按需</button><button class="chip" data-filter="选修">选修</button></div><div class="software-list">${state.software.map((s,i)=>`<details class="software-card" id="software-${esc(s.id)}" data-stage="${esc(s.stage)}" ${detail===s.id?'open':''}><summary><span class="software-number">${String(i+1).padStart(2,'0')}</span><span class="software-card-title"><b>${esc(s.name)}</b><small>${esc(s.category)} · ${esc(s.summary)}</small></span><span class="tag ${s.stage==='基础必修'?'blue':''}">${esc(s.stage)}</span></summary><div class="software-content"><div class="software-properties"><p><b>执行位置</b>${esc(s.scope)}</p><p><b>资源要求</b>${esc(s.resource)}</p><p><b>许可说明</b>${esc(s.license)}</p></div><a href="${safeLink(s.source)}" target="_blank" rel="noopener noreferrer">查看官方文档 ↗</a>${s.steps.map((step,n)=>`<section><h3><span class="step-count">${n+1}</span>${esc(step.title)}</h3><p>${esc(step.explanation)}</p>${step.command?commandBlock(step.command,''):''}<p class="expected"><b>成功表现</b> ${esc(step.expected)}</p><p class="troubleshooting"><b>遇到问题</b> ${esc(step.troubleshooting)}</p></section>`).join('')}<div class="learning-note"><b>安装完成后的验证</b><pre>${esc(s.verify)}</pre></div><details><summary>卸载与清理</summary><pre>${esc(s.uninstall)}</pre></details><ul>${s.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></div></details>`).join('')}</div>`;$('#refresh-health').onclick=async()=>{await refreshHealth();renderSoftware(detail)};$$('[data-filter]').forEach(b=>b.onclick=()=>{$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));$$('.software-card').forEach(c=>c.hidden=b.dataset.filter!=='all'&&b.dataset.filter!==c.dataset.stage)});if(detail)setTimeout(()=>$('#software-'+CSS.escape(detail))?.scrollIntoView({block:'start'}),50)}
function commandBlock(command,description){return `<div class="command-card"><div class="command-top"><span>终端命令</span><button class="copy-button" data-copy="${esc(command)}">复制命令</button></div><pre><code>${esc(command)}</code></pre>${description?`<p>${esc(description)}</p>`:''}</div>`}
function renderTracks(){root.innerHTML=heading('NEXT CHAPTER <span>第 07 — 12 周</span>','选择你的工程方向','共同基础之后，选择一条路线深入。以下是进阶项目规划，完整实验尚未上线。')+`<div class="track-grid">${state.course.tracks.map((t,i)=>`<article class="track-card"><div class="track-index">0${i+1}<span class="tag">进阶规划</span></div><h2>${esc(t.title)}</h2><p>${esc(t.summary)}</p><div class="skill-tags">${t.skills.map(s=>`<span>${esc(s)}</span>`).join('')}</div><ol class="milestones">${t.projects.map(p=>`<li><span>第 ${esc(p.weeks)} 周</span><h3>${esc(p.title)}</h3><p>${esc(p.deliverable)}</p></li>`).join('')}</ol><div class="software-links">${t.softwareIds.map(id=>`<button class="secondary" data-software="${esc(id)}">${esc(state.software.find(s=>s.id===id)?.name||id)} ↗</button>`).join('')}</div></article>`).join('')}</div><section class="lesson-body sources-section"><h2>从岗位要求到项目证据</h2><p>把软件、控制和机械知识连接起来，并保留你解决问题的证据。阅读招聘信息时，分清应届要求、优先技能、经验年限和地区条件；课程训练不等于录用保证。</p><div class="source-list">${state.course.sources.map(s=>`<a href="${safeLink(s.url||s.source)}" target="_blank" rel="noopener noreferrer">${esc(s.title||s.name)} ↗</a>${s.note?`<p>${esc(s.note)}</p>`:''}`).join('')}</div></section>`}
function renderPortfolio(){const ps=state.progress.preferences;const count=state.course.lessons.filter(l=>completed(l.id)).length;root.innerHTML=heading('LEARNING RECORD <span>把过程变成作品</span>','学习与工程作品','自动检查记录、项目文件和你的分析，共同构成可复现的学习证据。')+`<div class="stat-grid"><div><span>基础单元完成</span><b>${count}<small> / 24</small></b></div><div><span>已通过真实实验</span><b>${state.progress.lessons.filter(p=>p.checked).length}<small> / 24</small></b></div><div><span>实验检查次数</span><b>${state.progress.attempts||0}</b></div><div><span>人工评审</span><b class="small-stat">未评审</b></div></div><div class="portfolio-grid"><section class="lesson-body"><h2>六个项目的学习记录</h2>${state.course.weeks.map(w=>`<div class="project-progress"><div><b>${String(w.id).padStart(2,'0')} · ${esc(w.project)}</b><button class="text-link" data-lesson="w${w.id}-1">继续学习 →</button></div><div class="lesson-checks">${state.course.lessons.filter(l=>l.week===w.id).map(l=>{const p=progressOf(l.id);return `<div><span>${esc(l.title)}</span><small>${p.read_at?'已读':'未读'} · 理解 ${p.score||0}% · ${p.checked?'实验通过':'实验待检查'}</small></div>`}).join('')}</div></div>`).join('')}</section><section class="lesson-body"><h2>你的作品说明</h2><form id="portfolio-form"><label class="field">学生作者<input name="studentName" maxlength="100" value="${esc(ps.studentName||'')}" placeholder="填写你的姓名"></label><label class="field">项目名称<input name="projectTitle" maxlength="200" value="${esc(ps.projectTitle||'虚拟电机速度闭环调试')}"></label><label class="field">项目复盘<textarea name="reflection" rows="9" maxlength="5000" placeholder="问题是什么？你用什么证据定位？如何验证修复？结果有什么局限？">${esc(ps.reflection||'')}</textarea></label><button class="primary" type="submit">保存作品说明</button></form><div class="learning-note"><b>课程作者与学生作者独立记录</b><p>课程作者：Connor He 和 Astra。你的项目应写明自己的姓名、贡献和实验结果。</p></div><div class="button-row"><button class="secondary" id="download-portfolio">导出学习记录</button><button class="secondary" id="download-teacher">教师使用说明</button></div><h3 class="rubric-title">项目评审建议</h3><p class="muted">正确性 40% · 复现性 25% · 排障证据 20% · 技术表达 15%。请同学或教师按照说明独立复现；平台不会把自评当作教师认证。</p></section></div>`;$('#portfolio-form').onsubmit=async e=>{e.preventDefault();try{await api('/preferences','POST',Object.fromEntries(new FormData(e.target)));state.progress=await api('/progress');toast('作品说明已保存在本机。')}catch(e){toast(e.message)}};$('#download-portfolio').onclick=()=>download('/portfolio/export','学习与作品记录.md');$('#download-teacher').onclick=()=>download('/teacher','教师使用说明.md')}
function renderMotor(){const c=state.motorConfig;root.innerHTML=heading('VIRTUAL COMMISSIONING <span>无需硬件 · 真实数值计算</span>','虚拟电机实验台','给定一个目标，观察控制器如何响应。调节参数、施加负载，再用曲线与指标解释结果。')+`<div class="motor-layout"><section class="motor-controls"><div class="panel-title">实验设置 <span class="tag blue">直流电机</span></div><div class="preset-row"><button class="chip" data-preset="open">开环启动</button><button class="chip" data-preset="normal">标准 PI</button><button class="chip" data-preset="fault">反馈反接</button></div><form id="motor-form"><label class="field">控制方式<select name="mode"><option value="closed" ${c.mode==='closed'?'selected':''}>速度闭环 PI</option><option value="open" ${c.mode==='open'?'selected':''}>恒压开环</option></select></label><div class="field-pair"><label class="field">目标转速 <span>rpm</span><input name="target_rpm" type="number" min="-6000" max="6000" step="50" value="${c.target_rpm}" required></label><label class="field">开环电压 <span>V</span><input name="voltage" type="number" min="-24" max="24" step="1" value="${c.voltage}" required></label></div><div class="field-pair"><label class="field">比例增益 Kp<input name="kp" type="number" min="0" max="5" step="0.01" value="${c.kp}" required></label><label class="field">积分增益 Ki<input name="ki" type="number" min="0" max="100" step="0.1" value="${c.ki}" required></label></div><p class="field-help">控制误差使用 rad/s。Kp 单位 V/(rad/s)，Ki 单位 V/rad。</p><div class="field-pair"><label class="field">负载转矩 <span>N·m</span><input name="load_Nm" type="number" min="-0.2" max="0.2" step="0.01" value="${c.load_Nm}" required></label><label class="field">加入负载时间 <span>s</span><input name="load_time" type="number" min="0" max="10" step="0.5" value="${c.load_time}" required></label></div><label class="field">仿真时长 <span>s</span><input name="duration" type="number" min="0.1" max="10" step="0.1" value="${c.duration}" required></label><label class="field">反馈故障<select name="fault"><option value="none" ${c.fault==='none'?'selected':''}>正常反馈</option><option value="units" ${c.fault==='units'?'selected':''}>把 rpm 当成 rad/s</option><option value="bias" ${c.fault==='bias'?'selected':''}>传感器偏差 +120 rpm</option><option value="reversed" ${c.fault==='reversed'?'selected':''}>反馈方向接反</option></select></label><label class="checkbox-field"><input name="anti_windup" type="checkbox" ${c.anti_windup?'checked':''}>启用积分抗饱和</label><button type="submit" id="run-motor" class="primary full-width">运行仿真实验</button><button type="button" id="cancel-motor" class="secondary full-width" hidden>停止计算</button></form><p class="field-help">电压受限于 ±24 V。计算使用仿真时间，与电脑运行速度无关。</p></section><div class="motor-results"><div id="motor-status" role="status" class="motor-status">${state.result?'上一次计算已完成，修改参数后可重新运行。':'先运行一次标准 PI，观察 2.5 s 的负载扰动。'}</div><div class="motor-metrics" id="motor-metrics"></div><section class="chart-card"><div class="chart-heading"><h2>速度响应</h2><div class="chart-legend"><span class="legend-blue">模型真实转速</span><span class="legend-orange">反馈测量值</span><span class="legend-dashed">目标转速</span></div></div><canvas id="speed-chart" role="img" aria-label="电机转速随仿真时间的变化"></canvas><div class="chart-caption">横轴：仿真时间 s · 纵轴：rpm</div></section><div class="chart-pair"><section class="chart-card"><h3>电枢电流 <small>A</small></h3><canvas id="current-chart" role="img" aria-label="电机电枢电流曲线"></canvas></section><section class="chart-card"><h3>驱动电压 <small>V</small></h3><canvas id="voltage-chart" role="img" aria-label="电机施加电压曲线"></canvas></section></div><div id="motor-warnings"></div><div class="button-row"><button id="export-motor" class="secondary" ${state.run?'':'disabled'}>导出参数与原始结果</button><button class="text-link" data-lesson="w6-3">学习闭环调参 →</button></div><details class="model-details"><summary>查看模型、单位与计算方法</summary><div class="equations">L · di/dt = u − R·i − Ke·ω<br>J · dω/dt = Kt·i − b·ω − τL</div><p>R = 2 Ω，L = 0.002 H，J = 0.0002 kg·m²，b = 0.0001 N·m·s/rad，Kt = Ke = 0.05（对应 SI 单位）。数字 PI 采样 1 ms，电机使用四阶 Runge–Kutta 法按 0.1 ms 子步积分，图表每 5 ms 采样。故障只影响测量反馈，不直接改动物理状态。</p><p>教学参数未经实机辨识；这是平均电机模型，不包含 PWM、热效应或真实驱动器。电流是计算结果，超限会提示，不伪造电流保护。</p><button class="text-link" data-software="openmodelica">安装 OpenModelica 做独立模型对照 →</button></details><details class="model-details"><summary>查看部分数值数据（完整数据可导出）</summary><div id="motor-table" class="table-scroll"></div></details></div></div>`;$('#motor-form').onsubmit=e=>{e.preventDefault();startMotor()};$('#cancel-motor').onclick=async()=>{if(state.activeRun)try{await api(`/motor/runs/${state.activeRun}/cancel`,'POST')}catch(e){toast(e.message)}};$('#export-motor').onclick=()=>download(`/motor/runs/${state.run}/export`,'virtual-motor-experiment.zip');$$('[data-preset]').forEach(b=>b.onclick=()=>{state.motorConfig={mode:b.dataset.preset==='open'?'open':'closed',voltage:12,target_rpm:900,kp:.08,ki:.6,duration:5,load_time:2.5,load_Nm:.03,fault:b.dataset.preset==='fault'?'reversed':'none',anti_windup:true};renderMotor()});drawMotor();syncMotorBusy();}
function syncMotorBusy(){
 if(!$('#motor-form'))return;
 $('#run-motor').disabled=state.motorPending;
 $('#cancel-motor').hidden=!state.activeRun;
 $$('[data-preset]').forEach(button=>button.disabled=state.motorPending);
 if(state.motorPending)$('#motor-status').textContent='正在求解电机与控制器方程…';
}
async function startMotor(){
 if(state.motorPending)return;
 const form=$('#motor-form'),data=Object.fromEntries(new FormData(form));
 for(const key of ['voltage','target_rpm','kp','ki','duration','load_time','load_Nm'])data[key]=Number(data[key]);
 data.anti_windup=form.elements.anti_windup.checked;
 state.motorConfig=data;state.motorPending=true;syncMotorBusy();
 try{
  const run=await api('/motor/runs','POST',data);state.activeRun=run.id;syncMotorBusy();
  let status;
  do{
   await new Promise(resolve=>setTimeout(resolve,250));
   status=await api('/motor/runs/'+run.id);
  }while(status.status==='running');
  if(status.status==='completed'){
   state.previous=state.result;state.result=status.result;state.run=run.id;
   if(state.view==='motor'){
    $('#motor-status').textContent='计算完成 · 结果来自本次参数的数值求解';
    drawMotor();$('#export-motor').disabled=false;
   }
  }else if(state.view==='motor')$('#motor-status').textContent=status.error||'计算已停止。';
 }catch(error){
  if(state.view==='motor')$('#motor-status').textContent=error.message;
  toast(error.message);
 }finally{
  state.activeRun=null;state.motorPending=false;syncMotorBusy();
 }
}
function metric(v,digits=2){return typeof v==='number'&&Number.isFinite(v)?v.toFixed(digits):'—'}
function drawMotor(){if(!$('#speed-chart'))return;const r=state.result,m=r?.metrics||{};$('#motor-metrics').innerHTML=[['最终转速',metric(m.final_rpm,1),'rpm'],['稳态误差',metric(m.steady_error_pct),'%'],['超调',metric(m.overshoot_pct),'%'],['峰值电流',metric(m.peak_current),'A']].map(([a,b,c])=>`<div><span>${a}</span><b>${b}<small>${c}</small></b></div>`).join('');plot($('#speed-chart'),r?.series||[],[{key:'rpm',color:'#3554cd'},{key:'measured_rpm',color:'#ce823e'},{key:'target_rpm',color:'#8b97ac',dash:[5,5]}]);plot($('#current-chart'),r?.series||[],[{key:'current',color:'#24846f'}]);plot($('#voltage-chart'),r?.series||[],[{key:'voltage',color:'#6c5ac4'}]);$('#motor-warnings').innerHTML=(r?.warnings||[]).map(w=>`<p class="warning-note">${esc(w)}</p>`).join('');$('#motor-table').innerHTML=r?`<table><thead><tr><th>t / s</th><th>转速 / rpm</th><th>电流 / A</th><th>电压 / V</th></tr></thead><tbody>${r.series.filter((_,i)=>i%Math.max(1,Math.floor(r.series.length/15))===0).slice(0,16).map(p=>`<tr><td>${metric(p.t,3)}</td><td>${metric(p.rpm)}</td><td>${metric(p.current,3)}</td><td>${metric(p.voltage,3)}</td></tr>`).join('')}</tbody></table>`:'<p>运行实验后显示数据。</p>'}
function plot(canvas,series,lines){const rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1,w=Math.max(rect.width,200),h=canvas.id==='speed-chart'?260:160;canvas.width=w*dpr;canvas.height=h*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const left=54,right=14,top=20,bottom=30,iw=w-left-right,ih=h-top-bottom;let ymin=0,ymax=1;const vals=series.flatMap(p=>lines.map(l=>p[l.key])).filter(Number.isFinite);if(vals.length){ymin=Math.min(0,...vals);ymax=Math.max(1,...vals);const pad=(ymax-ymin)*.08;ymin-=pad;ymax+=pad}const end=series.at(-1)?.t||state.motorConfig.duration||5;ctx.font='11px system-ui';ctx.textAlign='right';for(let i=0;i<=4;i++){const y=top+ih*i/4;ctx.strokeStyle='#e9edf4';ctx.setLineDash([]);ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke();ctx.fillStyle='#8793a6';ctx.fillText((ymax-(ymax-ymin)*i/4).toFixed(Math.abs(ymax)>50?0:1),left-9,y+4)}ctx.textAlign='center';for(let i=0;i<=5;i++)ctx.fillText((end*i/5).toFixed(1),left+iw*i/5,h-7);if(!series.length){ctx.fillStyle='#97a2b4';ctx.font='13px system-ui';ctx.fillText('运行实验后显示计算曲线',left+iw/2,top+ih/2);return}for(const line of lines){ctx.strokeStyle=line.color;ctx.lineWidth=1.9;ctx.setLineDash(line.dash||[]);ctx.beginPath();series.forEach((p,i)=>{const x=left+p.t/end*iw,y=top+(ymax-p[line.key])/(ymax-ymin)*ih;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}ctx.setLineDash([])}
function confirmAction(title,message){const dialog=$('#confirm-dialog');$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;dialog.showModal();return new Promise(resolve=>{$('#confirm-cancel').onclick=()=>dialog.close('cancel');$('#confirm-ok').onclick=()=>dialog.close('ok');dialog.onclose=()=>resolve(dialog.returnValue==='ok')})}
document.addEventListener('click',async e=>{const view=e.target.closest('[data-view]');if(view)navigate(view.dataset.view);const lesson=e.target.closest('[data-lesson]');if(lesson)navigate('learn',lesson.dataset.lesson);const software=e.target.closest('[data-software]');if(software)navigate('software',software.dataset.software);const copy=e.target.closest('[data-copy]');if(copy){try{await navigator.clipboard.writeText(copy.dataset.copy);const text=copy.textContent;copy.textContent='已复制';setTimeout(()=>copy.textContent=text,1500)}catch{toast('浏览器未允许剪贴板访问，请选中命令复制。')}}});
$('.menu-toggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#environment-button').onclick=()=>navigate('software');window.addEventListener('hashchange',render);let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(state.view==='motor')drawMotor()},120)});
async function init(){try{const session=await fetch('/api/session');if(!session.ok)throw Error('请使用 ./start.sh 启动完整本地服务。');state.token=(await session.json()).token;const [course,software,progress]=await Promise.all([api('/content/curriculum'),api('/content/software'),api('/progress')]);state.course=course;state.software=software;state.progress=progress;state.lesson=progress.preferences.lastLesson||'w1-1';await refreshHealth();render();registerTools()}catch(e){$('#environment-label').textContent='服务尚未就绪';toast('课程服务尚未就绪。'+e.message)}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'read_course_progress',description:'读取本机课程学习和实验验收进度。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>api('/progress')},{name:'open_course_lesson',description:'打开指定课程单元，不执行终端命令或标记完成。',inputSchema:{type:'object',properties:{lessonId:{type:'string'}},required:['lessonId'],additionalProperties:false},execute:async input=>{if(!state.course.lessons.some(l=>l.id===input.lessonId))throw Error('未知课程');navigate('learn',input.lessonId);await new Promise(r=>setTimeout(r,0));return {lessonId:input.lessonId,title:currentLesson().title}}}];for(const tool of tools)try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
init();
